// Differential probe for weapon_combat part D (swing scheduling + attack table).
//
// tc_swing_bodies.inc is generated by extract.py from the sibling TrinityCore
// checkout (7f3d43b): RollMeleeOutcomeAgainst, MeleeSpellHitResult, every
// chance getter, MeleeSpellMissChance, ApplyAttackTimePercentMod,
// UpdateAttackTimeField, resetAttackTimer, CalcMeleeAttackRageGain,
// Player::GetExpertiseDodgeOrParryReduction, Player::GetBlockPercent, the
// DealMeleeDamage parry-haste block and the crit/block/glancing cases of
// CalculateMeleeDamage.  This file supplies one stub class whose accessors
// read a key/value configuration; nothing of the arithmetic or ordering is
// re-typed here.
//
// Build: make   (g++ -std=c++20 -O0 -ffp-contract=off)
// Protocol (one request per line, one reply line):
//   clear                         -> ok        (drop all configuration)
//   set <key> <number>            -> ok        (see Unit accessors for keys; "a." attacker, "v." victim, "s." spell)
//   white <0|1>                   -> RLE of RollMeleeOutcomeAgainst over urand = 0..9999: "outcome@first ..."
//   spell                         -> RLE of MeleeSpellHitResult over urand = 0..9999
//   chance <dodge|parry|block|miss|missspell|crit> <att>   -> float (%.9g)
//   atkmod <timer> <base> <pct> <val> <apply>  -> "<timer> <pct %.9g> <field>"
//   reset <base> <pct> <att>      -> timer
//   parry <off> <base> <baseoff> <basemh> <haveoh> -> "<off> <base>"
//   rage <base> <att>             -> uint32
//   blockpct <shieldblock> <armorconstant> -> float
//   pct <base> <pct>              -> CalculatePct<uint32,float>
//   crit <damage> <multiplier>    -> damage after the MELEE_HIT_CRIT case
//   block <damage> <victimIsPlayer> <shieldblock> <armorconstant> <blockcrit> <critmult> -> "<damage> <blocked>"
//   glancing <damage> <attackerLevel> <victimLevel> -> "<damage> <clean>"
//   f32 <expr-op> ...             (not provided: Python owns binary32 emulation)

