static std::map<std::string, double> g_cfg;
static double cf(std::string const& key, double def = 0.0)
{
    auto it = g_cfg.find(key);
    return it == g_cfg.end() ? def : it->second;
}

static uint32 g_roll = 0;
uint32 urand(uint32 /*min*/, uint32 /*max*/) { return g_roll; }

